import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    """
    Extracts and converts data from a specified HTML table based on the given 'table_id' 
    on a webpage into a Pandas DataFrame.
    """
    # Perform the HTTP request
    response = requests.get(url)
    # Raise HTTPError for unsuccessful status codes
    response.raise_for_status()

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', {'id': table_id})

    # Raise ValueError if the table is not found
    if table is None:
        raise ValueError("Table with the specified ID not found.")

    # Check for data rows (<tr> tags)
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()

    # Use pandas read_html to parse the table
    # We convert the table element to a string to pass to read_html
    try:
        dfs = pd.read_html(StringIO(str(table)))
        if dfs:
            return dfs[0]
        else:
            return pd.DataFrame()
    except ValueError:
        # This handles cases where read_html might fail to parse the table structure
        return pd.DataFrame()

